def solve_game(N):
    s = [False] * (N + 1)  # False for Losing, True for Winning
    s[N] = False
    for n in range(N - 1, 0, -1):
        can_move_to_losing = False
        # Move to n+1
        if n + 1 <= N and not s[n + 1]:
            can_move_to_losing = True
        # Move to 2*n
        if 2 * n <= N and not s[2 * n]:
            can_move_to_losing = True
        s[n] = can_move_to_losing
    return s[1] # True if N is type B, False if N is type A

